\label{theo:attractors1}
    The following hold:
    \begin{enumerate}
        \item[(a)] If the function $\rho$ is such that there exists an $\varepsilon>0$ for which
            \begin{equation}
                |\rho (r)| \lesssim r^{3/2-\varepsilon}+1,  \tag{Compl-I}\label{eq:Compl-I}
            \end{equation}
            then the RDS $\varphi$ induced by \eqref{SDE2} is strongly complete (cf.~Definition \ref{def:compl}).
        \item[(b)] If the function $\rho$ satisfies 
    \begin{equation}
        |\rho (r)| \lesssim r+1,  \tag{PBAtt}\label{eq:PBAtt}
    \end{equation}
    then the RDS $\varphi$ induced by \eqref{SDE2} admits a pull-back set attractor (cf.~Definition \ref{def:Attr}).
    \end{enumerate}

\label{theo:attractors2}
    The following hold:
    \begin{enumerate}
        \item[(a)] If the function $\rho$ satisfies
        \begin{equation}
           \int_0^\infty \left(1\vee\sup_{r' \in [0, r]} |\rho'(r')|\right)^{-1/3} \mathrm{d} r = \infty,\tag{Compl-II} \label{eq:Compl}
        \end{equation}



        then the RDS $\varphi$ induced by \eqref{SDE2} is strongly complete.
        \item[(b)] There exists a constant $K_1>0$, independent of $\rho$, with the property that if the function $\rho$, for some $r^*>0$,  satisfies 
        \begin{equation}
            |\rho'(r)| \leq K_1\,r^3,\quad\forall\, r\geq r^*,\tag{Attr} \label{eq:Attr}
        \end{equation}
       then the RDS $\varphi$ induced by \eqref{SDE2} admits a weak set attractor (cf.~Definition \ref{def:Attr}).
    \end{enumerate}

\label{theo:BlowUpShort}
The following hold:
\begin{enumerate} 
\item[(a)] There exists a constant $K_2>0$, independent of $\rho$, with the property that if the function $\rho$, for some $r^*>0$,  satisfies
\begin{equation}
 |\rho'(r)|\geq K_2 \,r^3 \quad \forall \, r\geq r^*,
\tag{NoAtt} \label{eq:NoAttr}
\end{equation}
as well as
\begin{equation}\label{eq:BasicAssumption}
    \limsup_{r \to \infty}\frac{|\rho''(r)|}{|\rho'(r)|}<\infty, \quad \text{and}\quad |\rho'(r)| \text{ increases monotonically on }[r^*,\infty),
\end{equation}
then the RDS $\varphi$ induced by \eqref{SDE2} does not admit a weak set attractor.


\item[(b)]If, moreover, 
\begin{equation}
\int_{r^*}^\infty \big|\rho'(r)\big|^{-1/3}\,\mathrm{d} r<\infty\tag{NoCom} \label{eq:NoCompl},
\end{equation}
then the RDS $\varphi$ induced by \eqref{SDE2} is not strongly complete. In particular, almost surely, there exists an initial condition for which the solution to \eqref{SDE2} goes to infinity in finite time.
\end{enumerate}

A \emph{metric dynamical system} (MDS) is a tuple $(\Omega,\mathcal F,\mathbb P,(\theta_t)_{t\in \mathbb R})$, such that the following hold. 
    \begin{enumerate}
        \item[(i)] $(\Omega, \mathcal F, \mathbb P)$ is a probability space.
        \item[(ii)] For each $t \in \mathbb R$, $\theta_t: \Omega \to \Omega$ is a map such that $(\omega, t)\mapsto \theta_t \omega$ is jointly measurable, $\theta_0 = \operatorname{id}_\Omega$, and $\theta_t \circ \theta_s = \theta_{s+t}$ for all $s, t\in \mathbb R$.
        \item[(iii)] The probability measure is $\theta$ invariant, that is $\mathbb P(\theta_t^{-1}(E)) = \mathbb P(E)$ for all $t\in \mathbb R$ and $E \in \mathcal F$.
    \end{enumerate}

\label{def:filtered}
    A \emph{filtered local random dynamical system} is a local RDS $(\theta, \varphi)$ for which the probability space $(\Omega, \mathcal F, \mathbb P)$ is equipped with a two-sided filtration $(\mathcal F_{s,t})_{-\infty < s\leq t < \infty}$ satisfying the following.
    \begin{enumerate}
        \item[(i)] For each $-\infty< s\leq t\leq u \leq v < \infty$, we have $\mathcal F_{t,u} \subseteq \mathcal F_{s, v}$.
        \item[(ii)] For each $-\infty< s\leq t< \infty$ and each $u \in \mathbb R$, we have $\theta_u^{-1}(\mathcal F_{s,t}) = \mathcal F_{s+u, t+u}.$
        \item[(iii)] For every $t \geq 0$, the map $\varphi(t, \cdot, \cdot): \Omega \times \mathbb R^d_\Delta \to \mathbb R^d_\Delta$ is measurable with respect to $\mathcal F_{0,t} \otimes \mathcal B(\mathbb R^d_\Delta)$.
        \item[(iv)] For each $t\geq 0$ and $s \geq 0$, the restricted shift $\theta: \Omega \times [0,t] \to \Omega$ is measurable as a map between the measurable spaces
        \begin{equation}\label{eq:prog}
            \theta: \big(\Omega \times [0,t], \mathcal F_{0, t+s} \otimes \mathcal B([0,t])\big) \to \big(\Omega, \mathcal F_{0,s}\big).
        \end{equation}
    \end{enumerate}

\label{prop:tau}
    Let $(\theta,\varphi)$ be a filtered local RDS. Then the following hold.
    \begin{enumerate}
        \item[(i)] For every compact $C\subset \mathbb R^d$, the random time $\tau^\star(\omega,C)$ is an $(\mathcal F_t)$-stopping time, so, in particular, $\tau^\star(\omega,x)$ is an $(\mathcal F_t)$-stopping time for every $x \in \mathbb R^d$.
        \item[(ii)] For every set $E \subseteq \mathbb R^d$ that is a countable union of compact sets, the random time $\tau^\star(\omega,E)$ is an $(\mathcal F_t^+)$-stopping time, so, in particular, $\tau^\star(\omega,\mathbb R^d)$ is an $(\mathcal F_t^+)$-stopping time.
        \item[(iii)] For every finite $(\mathcal F_t^+)$-stopping time $\tau$, we have the inclusion
        \begin{equation}\label{eq:TauShift}
            \theta_\tau^{-1}(\mathcal F_t^+) \coloneqq \big\{\{\omega \in \Omega: \theta_{\tau(\omega)} \omega \in E\} : E \in \mathcal F_t^+\big\} \subseteq \mathcal F_{t+\tau}^+.
        \end{equation}
        Here $\mathcal F_{t +\tau}^+$ denotes the stopped $\sigma$-algebra
        $$\mathcal F_{t+ \tau}^+\coloneqq \big\{E\in \mathcal F: E\cap \{\omega \in \Omega :\tau(\omega) \leq s\} \in \mathcal F_{t+s}^+, ~\forall\, s\geq 0\big\}$$
        In particular, if $\tau_1$ and $\tau_2$ are finite $(\mathcal F_t^+)$-stopping times, their concatenation 
        \begin{equation}\label{eq:tauSum}
            \tau_3(\omega) \coloneqq \tau_1(\omega) + \tau_2(\theta_{\tau_1(\omega)}\omega)
        \end{equation}
        is an $(\mathcal F_t^+)$-stopping time as well.
    \end{enumerate}

(i): Let $C\subset \mathbb R^d$ be compact. We want to show that $\tau^\star(\omega,C)$ is an $ (\mathcal{F}_t)$-stopping time, that is, $\{\omega \in \Omega: \tau^\star(\omega, C)\leq t\} \in \mathcal F_t$ for every $t \geq 0$. 
     Since the survival domain $D_\varphi(\omega)$ is open, $\tau^\star(\omega,x)$ is lower semicontinuous in $x$ for every $\omega \in \Omega$ and attains its minimum on the compact set $C$. Furthermore, by the time-continuity of trajectories, we have that if $\tau^\star(\omega,C)\leq t$, then the set 
     \begin{equation}\label{eq:imageSet}
         \{\varphi(s,\omega,x) : (s,x) \in ([0,t]\times C) \cap D_\varphi(\omega)\}
     \end{equation}
     is unbounded. Conversely, if $\tau^\star(\omega,C) >t$, then the compact set $[0,t]\times C$ is in the survival domain $D_\varphi$ so, by restricted continuity, the set \eqref{eq:imageSet} is bounded. Hence, we can write
     \begin{align*}
         \{\omega \in \Omega: \tau^\star(\omega, C)\leq t\} &= \bigcap_{n \in \mathbb N} \bigcup_{s \in [0,t]} \bigcup_{x \in C} \{\omega \in \Omega: (s,x) \in D_\varphi(\omega) \text{ and } |\varphi(s,\omega,x)| > n\}\\
         &= \bigcap_{n \in \mathbb N} \bigcup_{s \in [0,t]\cap \mathbb Q} \bigcup_{x \in C^*} \{\omega \in \Omega: (s,x) \in D_\varphi(\omega) \text{ and } |\varphi(s,\omega,x)| > n\},
     \end{align*}
     where $C^*\subseteq C$ is a countable dense subset and we use restricted continuity again. Since every event in the countable intersection of countable unions is in $\mathcal F_t$ by definition, we can conclude $\{\omega \in \Omega: \tau^\star(\omega, C)\leq t\} \in \mathcal F_t$ completing the proof.

    (ii) follows directly from (i), since countable infimums of $(\mathcal F_t)$-stopping times are $(\mathcal F_t^+)$-stopping times.

    (iii) Let $\tau$ be an $(\mathcal F^+_t)$-stopping time, $t\geq 0$ and $E \in \mathcal F_t^+$. Define the stochastic process $(E_s)_{s\geq 0}$ by 
    $$E_s(\omega) \coloneqq \mathds 1_E(\theta_s\omega).$$
    By Definition \ref{def:filtered} (iv), it is progressively measurable with respect to $(\mathcal F^+_{t+s})_{s\geq 0}$, that is, for each $u \geq 0$, the restriction $(E_s)_{s\in [0,u]}$ is $(\mathcal B([0,u])\otimes \mathcal F^+_{t+u})$-measurable. Hence, $E_\tau = \mathds 1_{\theta_\tau^{-1}(E)}$ is $\mathcal F^+_{t+\tau}$-measurable and $\theta_\tau^{-1}(E) \in \mathcal F^+_{t+\tau}$, establishing \eqref{eq:TauShift}. To show \eqref{eq:tauSum}, let $\tau_1$ and $\tau_2$ be $(\mathcal F_t^+)$-stopping times and $\tau_3$ be defined as in \eqref{eq:tauSum}. For each $t \geq 0$, we have
    \begin{align*}
        \{\omega \in \Omega : \tau_3(\omega) <t\} &= \bigcup_{s\in [0,t] \cap \mathbb Q} \{\omega \in \Omega : \tau_1(\omega) < s\} \cap \{\omega \in \Omega : \tau_2(\theta_{\tau_1(\omega)}\omega) < t-s\}\\
        &= \bigcup_{s\in [0,t] \cap \mathbb Q} \{\omega \in \Omega : \tau_1(\omega) < s\} \cap \theta_{\tau_1}^{-1}(\{\omega \in \Omega : \tau_2(\omega) < t-s\}).
    \end{align*}
    By \eqref{eq:TauShift}, the event $\theta_{\tau_1}^{-1}(\{\omega \in \Omega : \tau_2(\omega) < t-s\})$ is in $\mathcal F^+_{t-s+\tau_1}$ and hence 
    $$ \{\omega \in \Omega : \tau_1(\omega) < s\} \cap \theta_{\tau_1}^{-1}(\{\omega \in \Omega : \tau_2(\omega) < t-s\}) \in \mathcal F_{t-s+s}^+=\mathcal F_{t}^+,$$
    for every $s \in [0,t].$ In particular, $\{\omega \in \Omega : \tau_3(\omega) <t\} \in \mathcal F_{t}^+$ and, by right-continuity of the filtration, we also get $\{\omega \in \Omega : \tau_3(\omega) \leq t\} \in \mathcal F_{t}^+$. Since this holds for all $t\geq 0$, the random time $\tau_3$ is a stopping time as claimed.

\label{def:compl}~
    \begin{enumerate}
        \item [(i)] A local RDS $\varphi$ is called \emph{weakly complete}, if we have $\mathbb P(\tau^\star(\omega, x) = \infty) = 1$, for every $x \in \mathbb R^d$.
        \item[(ii)]The local RDS $\varphi$ is called \emph{strongly complete}, if  ${\mathbb P(\tau^\star(\omega, \mathbb R^d) = \infty) = 1}$.
    \end{enumerate}

A filtered local RDS $(\theta,\varphi)$ has the \emph{strong Markov property} if its filtration satisfies the following. For every finite $(\mathcal F_t^+)$-stopping time $\tau$ and every bounded random variable $Y$ that is measurable with respect to $\mathcal F_{0, \infty}$, we have
    \begin{equation}\label{eq:StrongMarkov}
        \mathbb E[Y(\theta_{\tau(\omega)}\omega)\mid \mathcal F_\tau^+] = \mathbb E[Y], \quad \text{almost surely}.
    \end{equation}

\label{def:Attr}
   A non-empty random compact $\varphi$-invariant set $(A(\omega))_{\omega \in \Omega}$ which is measurable with respect to the past is called 
	\begin{enumerate}
		\item[(i)] \emph{weak set attractor}, if for every deterministic bounded set $E \subset \mathbb R^d$, we have
            $$\operatorname{dist} \big(\varphi(t, \omega, E), A(\theta_t \omega)\big) \to 0, ~\text{in probability},$$
            where $\operatorname{dist}(E_1, E_2):= \sup_{x\in E_1}\inf_{y\in E_2}|x-y|$ is the Hausdorff semi-distance.
		\item[(ii)] \emph{pull-back set attractor}, if for every tempered random compact set $(E(\omega))_{\omega \in \Omega}$, we have
		\begin{equation*}
		\operatorname{dist} \big(\varphi(t, \theta_{-t} \omega, E(\theta_{-t}\omega)), A(\omega)\big) \to 0 , \quad \text{for almost all } \, \omega \in \Omega.
		\end{equation*}
	\end{enumerate}

\label{rmk:WeakSetAttr}
 For pull-back set attractors, it is useful to consider attraction by all tempered compact random sets, since this leads to a notion of attractor which is invariant under certain random coordinate transformations, such as the ones considered in Section \ref{sec:ProofAttrI}. For weak set attractors we only require attraction of deterministic sets for simplicity, even though our definition also implies that if $A(\omega)$ is a weak set attractor and $E(\omega)$ is a tempered set, then 
$$\operatorname{dist} \big(\varphi(t, \omega, E(\omega)), A(\theta_t \omega)\big) \to 0, ~\text{in probability}.$$
This can be seen as follows. We need to show that for every $\varepsilon, \delta > 0$, there exists a $T>0$, such that for all $t \geq T$
     \begin{equation}\label{eq:WeakSetAttr}
         \mathbb P \big(\operatorname{dist}\big(\varphi(t, \omega, E(\omega)), A(\theta_t \omega)\big)>\varepsilon \big) < \delta.
     \end{equation}
     Choose $R>0$, such that $\mathbb P(E(\omega) \subseteq \bar B_0(R)) > 1-\delta/2$, where $\bar B_0(R)$ is the closure of $B_0(R)$. Now, use the fact that there exists a $T\geq 0$ such that \eqref{eq:WeakSetAttr} holds for all $t \geq T$ if $E(\omega)$ is replaced with the deterministic set $\tilde E = \bar B_0(R)$ and $\delta$ is replaced with $\delta/2$.

\label{TransformSystems}
Assume that the solution $\Psi$ to~\eqref{eq:Psi} exists for all $t\geq0$. Then:
\begin{itemize}
  \item [(i)]
  The random dynamical system $\varphi: [0,\infty)\times \widehat\Omega\times \mathbb R^2\rightarrow \mathbb R^2$, defined by
  \begin{equation}\label{Transformation_Evolution}
   \varphi(t,\omega,x):= H(\theta_t\omega,\Psi(t,\omega,H(\omega)^{-1}x))\,,
  \end{equation}
  is generated by the stochastic differential equation \eqref{SDE2}.
  \item [(ii)]
  If the random dynamical system $\Psi$ has a pull-back set attractor, then also the random dynamical system $\varphi$ has a pull-back set attractor.
  \end{itemize}

\label{TechnicalLemma}
 Assuming  condition~\eqref{eq:PBAtt}, there exist stationary processes $\gamma$ and $\beta$
  such that for $x\in\mathbb R^2$ and $\eta_0  \geq  \left|x\right|^2$, we have, with $\eta$ given by~\eqref{Estimate07},
  \begin{equation}\label{etaest}
  \left|\Psi(t,\omega,x)\right|^2
  \leq 2 \eta(t,\omega,\eta_0 )\,,
  \end{equation}
  which implies that the solution $\Psi(t,\omega,x)$ exists for all $t\ge0$.

\label{lemm:ballcrit}Consider a filtered local RDS $(\theta, \varphi)$ on $\mathbb R^d$ that satisfies the strong Markov property \eqref{eq:StrongMarkov}.
For an increasing sequence of positive radii $0 < r_1 < r_2 < \dots$ with $r_n\to \infty$, let $B_n := B_{0}(r_n)$ be the centered open ball with radius $r_n$ and let $C_n \coloneqq \bar B_n$ be its closure. Define two sequences of random times $\tau^\uparrow_1, \tau^\uparrow_2, \dots$ and $\tau^\downarrow_1, \tau^\downarrow_2, \dots$ by
\begin{align*}
    \tau^\uparrow_n(\omega) &:= \inf\{t \geq 0 : \varphi(t, \omega, C_n) \nsubseteq B_{n+1}\}, ~ \forall\, n\geq 1,\\
    \tau^\downarrow_n(\omega) &:= \inf\{t \geq 0 : t< \tau^\star(\omega,C_n)\text{ and }\varphi(t, \omega, C_n) \subseteq C_{n-1}\}, ~ \forall\, n\geq 2
\end{align*}
and $\tau^\downarrow_1(\omega) = \infty$. 
\begin{enumerate}
    \item[(i)] If there exists a sequence $t_1, t_2, \dots$ of positive times with  $\sum_{n = 1}^\infty t_n = \infty$, such that 
    $$\liminf_{n \to \infty} \mathbb P (\tau^\uparrow_n \geq t_n) > 0,$$
    then $\varphi$ is strongly complete.
    \item[(ii)] If there exists a sequence $t_1, t_2, \dots$ of positive times with $t_n \to 0$, such that 
    \begin{equation}\label{ineq:ballcritattrcond}
        \liminf_{n \to \infty} \mathbb P (\tau^\downarrow_n < \tau^\uparrow_n \wedge t_n) > \frac{1}{2},
    \end{equation}
    then $\varphi$ admits a weak set attractor.
\end{enumerate}

\label{lemm:contraction}
Let $X(t) = \varphi(t, \omega, x)$ be a solution to \eqref{SDE2} and let $\chi_X: [0,\infty) \to \mathbb R$ be given by                                                    
\begin{equation}\label{eq:chidef}
    \chi_X(t) = \int_0^t \rho(|X(s)|)\,\mathrm{d} s.
\end{equation}
Then 
\begin{equation}\label{contractionBound}
    |\varphi(t, \omega, x)| \leq e^{-t}\,|x| +\sup_{s \in [0,t]} \left|\int_s^t \mathcal R(\chi_X(u)) \,\mathrm{d} W(u)\right|.
\end{equation}

Let $Y: [0,\infty) \to \mathbb R^2$ and $\widetilde W: [0, \infty) \to \mathbb R^2$ be given by
\begin{align*}
    Y(t) &:= \mathcal R(\chi_X(t)) X(t) &&\text{and}& \widetilde W(t) := \int_0^t \mathcal R(\chi_X(s)) \,\mathrm{d} W(s).
\end{align*}
A simple calculation shows that $Y$ satisfies the SDE
\begin{equation*}\label{sde:xtilde}
    \mathrm{d} Y(t) = - Y(t) \,\mathrm{d} t + \mathrm{d} \widetilde W(t).
\end{equation*}
By variation of constants, $Y(t)$ is given by
$$Y(t) = e^{-t}\,Y(0) + \int_0^t e^{s-t} \,\mathrm{d}\widetilde W(s).$$
Since $ |X(t)| = |Y(t)|$, we get the bound
$$|X(t)| \leq e^{-t}\, |X(0)| + \left| \int_0^t e^{s-t} \,\mathrm{d}\widetilde W(s)\right|.$$
Finally, using integration by parts, we can estimate
\begin{align*}
   \left| \int_0^t e^{s-t} \,\mathrm{d}\widetilde W(s)\right| &= \left| \widetilde W(t) - \int_0^t e^{s-t}\, \widetilde W(s) \,\mathrm{d} s\right|\\
   &= \left| e^{-t}\left(\widetilde W(t)-\widetilde W(0)\right) + \int_0^t e^{s-t}\left(\widetilde W(t)-\widetilde W(s)\right) \,\mathrm{d} s\right| \\
   &\leq  \sup_{s \in [0,t]}  \left|\widetilde W(t)-\widetilde W(s)\right| = \sup_{s \in [0,t]} \left|\int_s^t \mathcal R(\chi_X(u)) \,\mathrm{d} W(u)\right|
\end{align*}
to complete the proof.

\label{lemm:youngloeve}
For any $b \in \mathbb R$, any $\beta, T\geq 0$ and every $q>0$, $Q_{b, \beta, T}$ is measurable and we have
\begin{enumerate}
    \item[(i)]  $\mathbb P (Q_{b, \beta, T} < q) > 0$ and 
    \item[(ii)] $\mathbb P (Q_{b, \beta, T} = \infty) = 0.$
\end{enumerate}

\label{lemm:contr2}
    Assume the setting of Lemma \ref{lemm:ballcrit}. Let $q_1, q_2, \dots$ be a sequence of positive real numbers satisfying 
    \begin{align}\label{eq:RQCond1}
       0\leq r_n-q_n < r_n + q_n &\leq r_{n+1}, ~\forall \, n \geq 1.
    \end{align}
    Define two sequences $b_1, b_2, \dots$ and $\beta_1, \beta_2, \dots$ by
    \begin{align*}
         b_n &:= \rho(r_n-q_n)&&
        \text{and}&\beta_n &:= 2q_n \sup_{r \in [r_n-3q_n, r_n + q_n]\cap [0,\infty)} |\rho'(r)|.
    \end{align*}
    \begin{enumerate}
        \item[(i)] For each $n\geq 1$ and each $t>0$, if $Q_{b_n,\beta_n, t}< q_n$ then $\tau^\uparrow_n > t.$ 
        \item[(ii)] Assume furthermore that
        \begin{align}\label{eq:RQCond2}
          0< r_n-3q_n <r_n-2q_n &\leq r_{n-1}, ~\forall \, n \geq 2,
    \end{align}
    and let the sequence $(T_n)$ be given by
   $$T_n = \frac{3q_n}{r_n-3q_n}.$$
        For each $n \geq 2$, if $Q_{b_n,\beta_n, T_n}< q_n$ then $\tau_n^\downarrow<T_n$, and by (i) even $\tau_n^\downarrow<\tau_n^\uparrow \wedge T_n$.
    \end{enumerate}

\label{lemm:QScaling}
 For each $b \in \mathbb R$, $\beta \geq 0$ and $T \geq 0$, we have
\begin{enumerate}
    \item[i)] $Q_{b,\beta, T} \stackrel{\mathclap{\normalfont\mbox{d}}}{=} Q_{0,\beta, T}$ and 
    \item[ii)] $Q_{0, \kappa\beta, \kappa^{-1}T} \stackrel{\mathclap{\normalfont\mbox{d}}}{=} \kappa^{-1/2}\,Q_{0,\beta, T},$ for each $\kappa >0$.
\end{enumerate}

Suppose $\rho$ satisfies \eqref{eq:Attr}, that is, there is a radius $r^*\geq 0$, such that 
    \begin{equation*}\label{ineq:rhoprimebound}
        |\rho' (r)| \leq C r^3, ~\forall \, r \geq r^*.
    \end{equation*}
    for some $0<C\leq K_1$ which is less than some universal constant $K_1>0$ to be determined. For a different constant $K>0$, also to be determined later, define sequences $(r_n)$, $(q_n)$, $(\beta_n^*)$ and $(t_n)$ by
    \begin{align*}
        r_n &:= K n^{1/2},& q_n &:= \frac{3}{8}Kn^{-1/2},& \beta_n^*&:= 3CK^4n,& t_n&:= 3n^{-1}.
    \end{align*}
    Furthermore, let $(b_n)$, $(\beta_n)$, and $(T_n)$ be sequences as defined in Lemma \ref{lemm:contr2}. The conditions \eqref{eq:RQCond1} and \eqref{eq:RQCond2} can be verified by the following elementary calculations:
\begin{align*}
     r_{n+1}-r_n &= K (\sqrt{n+1}-\sqrt{n}) = \frac{K}{\sqrt{n+1}+\sqrt{n}}\geq \frac{K}{(1+\sqrt{2})\sqrt{n}}> q_n, &&\forall n \geq 1,\\
    r_n-r_{n-1} &= K (\sqrt{n}-\sqrt{n-1}) = \frac{K}{\sqrt{n}+\sqrt{n-1}} \leq \frac{K}{(1+\sqrt{1/2})\sqrt{n}} \leq 2q_n,& &\forall \, n \geq 2,\\
    r_n-3q_n &= K\left(\sqrt{n}-\frac{9}{8\sqrt{n}}\right) \geq K\left(\sqrt{2}-\frac{9}{8\sqrt{2}}\right)>0,& &\forall \, n \geq 2.
\end{align*}
Let $n^* \in \mathbb N$ denote the smallest integer $n^*\geq 2$ satisfying $r_{n^*}-3q_{n^*}\geq r^*$. For all $n\geq n^*$, we have
\begin{align*}
    \beta_n &= 2q_n \sup_{r\in[r_n-3q_n, r_n+q_n]}|\rho'(r)| \leq 2 q_n C(r_n+q_n)^3 \leq 2 q_n Cr_{n+1}^3 \\
    &= \frac{3}{4}CK^4 n^{-1/2}(n+1)^{3/2}\leq \frac{3\cdot 2^{3/2}}{4}CK^4 n < 3CK^4 n = \beta_{n}^*, \text{ and}\\
    T_n &= \frac{3q_n}{r_n-3q_n} = \frac{\tfrac{9K}{8}n^{-1/2}}{Kn^{1/2}- \tfrac{9K}{8} n^{-1/2}} = \frac{1}{\tfrac{8}{9}n-1} < \frac{3}{n} = t_n.
\end{align*}
Note that the dependence on $n$ in $\beta_n$, $q_n$ and $t_n$ matches the scaling in Lemma \ref{lemm:QScaling}. We can use this, together with Lemma \ref{lemm:contr2} and the monotone dependence of $Q$ on $\beta$ and $t$, to get the bound

    \begin{align*}
        \mathbb P\left(\tau^\downarrow_n < \tau^\uparrow_n \wedge t_n \right) &\geq \mathbb P\left(\tau^\downarrow_n < \tau^\uparrow_n \wedge T_n \right) \geq   \mathbb P(Q_{b_n, \beta_n, T_n} < q_n)\\
        &\geq \mathbb P(Q_{b_n, \beta_n^*, t_n} < q_n)= \mathbb P\left(Q_{0, \beta_1^*, t_1} < q_1\right) 
    \end{align*}
    for all $n \geq n^*$. In particular, we have
    $$\liminf_{n \to \infty}\mathbb P\left(\tau^\downarrow_n < \tau^\uparrow_n \wedge t_n \right) \geq \mathbb P\left(Q_{0, \beta_1^*, t_1} < q_1\right),$$
    so in order to establish \eqref{ineq:ballcritattrcond}, it remains to show $\mathbb P\left(Q_{0, \beta_1^*, t_1} < q_1\right)>\frac{1}{2}$.
    Recall that the constant $K>0$ was arbitrary so far and fix $K=C^{-1/4}$, such that $\beta^*_1 = 3$ and $t_1 = 3$ no longer depend on $C$. As a consequence of Lemma \ref{lemm:youngloeve} (ii), there exists a constant $Q^*> 0$ such that $\mathbb P(Q_{0, 3,3} < Q^*) > \frac{1}{2}$. Set $K_1 = \frac{1}{51}{Q^*}^{-4}$. Then 
    $$q_1 = \frac{3}{8}K = \frac{3}{8}C^{-1/4} \geq \frac{3}{8}K_1^{-1/4} = \frac{3}{8} 51^{1/4} Q^*>Q^*.$$
     and thus indeed $\mathbb P\left(Q_{0, \beta_1^*, t_1} < q_1\right)>\frac{1}{2}$. Therefore, \eqref{ineq:ballcritattrcond} holds and, by Lemma \ref{lemm:ballcrit}, the random dynamical system $\varphi$ admits a weak set attractor.

\label{theo:BlowUp}
The following hold:
\begin{enumerate} 
\item[(a)] There exists a constant $K_2>0$, independent of $\rho$, with the property that if the function $\rho$, for some $r^*>0$,  satisfies
\begin{equation}
 |\rho'(r)|\geq K_2 \,r^3 \quad \forall \, r\geq r^*,
\tag{NoAtt} \label{eq:NoAttr2}
\end{equation}
as well as
\begin{equation}\label{eq:BasicAssumption2}
    \limsup_{r \to \infty}\frac{|\rho''(r)|}{|\rho'(r)|}<\infty, \quad \text{and}\quad |\rho'(r)| \text{ increases monotonically on }[r^*,\infty),
\end{equation}
then the following hold.

\begin{enumerate}
    \item[(a.i)] The RDS $\varphi$ does not admit a weak set attractor.

    \item[(a.ii)] In particular, for every compact, connected set $\mathcal M\subseteq \mathbb R^2$ that contains at least two points, there is a positive probability that the radius of its image under the flow grows at least exponentially, that is, 
$$\mathbb P\left(\tau^\star(\omega,\mathcal M) <\infty \text{ or } \liminf_{t \to \infty} \frac{1}{t} \log (\operatorname{rad}(\varphi(t,\omega,\mathcal M)))>0\right) >0.$$

    \item[(a.iii)] Moreover, for every $\varepsilon >0$, there exists a radius $R$ such that if $\mathcal M$ contains some point $x$ with $|x|\leq 1$ and satisfies $\operatorname{rad}(\mathcal M) \geq R$, then this probability is at least $1-\varepsilon$.
\end{enumerate}





\item[(b)]If, additionally, 
\begin{equation}
\int_{r^*}^\infty \big|\rho'(r)\big|^{-1/3}\,\mathrm{d} r<\infty\tag{NoCom} \label{eq:NoCompl2},
\end{equation}
then the following hold.

\begin{enumerate}
    \item[(b.i)] The RDS $\varphi$ is not strongly complete.
    \item[(b.ii)]In particular, for every compact, connected set $\mathcal M\subseteq \mathbb R^2$ that contains at least two points, there is a positive probability that there exists a point $x \in \mathcal M$ and a time $T>0$, such that
    $$\lim_{t \nearrow T} |\varphi(t,\omega,x)| = \infty.$$ 
    \item[(b.iii)] Moreover, for every $\varepsilon >0$, there exists a radius $R$ such that if $\mathcal M$ contains some point $x$ with $|x|\leq 1$ and satisfies $\operatorname{rad}(\mathcal M) \geq R$, then with probability at least $1-\varepsilon$ this happens at time $T\leq\varepsilon$.

\end{enumerate}





\end{enumerate}

\label{lemm:BlowUpCrit}
Consider a filtered local RDS $(\theta, \varphi)$ on $\mathbb R^d$ which satisfies the strong Markov property.
    As in Lemma \ref{lemm:ballcrit}, let $0<r_1<r_2<\dots$ be an increasing sequence of radii with $r_n \to\infty$ and denote by $B_n = B_{0}(r_n)$ the centered open balls with radius $r_n$ and by $C_n$ their closures. 
    Let $\tau_n(\omega,x)$ denote the $(\mathcal F_t)$-stopping time 
    $$\tau_n(\omega,x) \coloneqq \inf\{t\geq 0: |\varphi(t,\omega,x)| = r_n\}.$$
    Depending on whether the radius of $x$ is larger or smaller than $r_n$, this describes either the first entry into the closed ball $C_n$ or the first exit of the open ball $B_n$.                                                               

    Let $t_2 \geq t_3\geq\dots$ be a decreasing sequence of positive times, $p^*\in (\frac{1}{2},1]$ and $\alpha \in (0, 2p^*-1)$. Define a ``growth rate" $m: \mathbb N \times \mathbb R_{>0}\to \mathbb N \cup \{\infty\}$ by
    \begin{equation}\label{eq:Growthrate}
        m(n,t) \coloneqq \sup \left\{m \geq n: \frac{1}{\alpha}\sum_{k=n}^{m-1} t_{k+1} < t \right\}.
    \end{equation}
    Recall that the radius of a set $\mathcal M\subseteq \mathbb R^d$ is given by $\operatorname{rad}(\mathcal M) \coloneqq \sup_{x\in \mathcal M} |x|$. 
    For any $n\in \mathbb N$, we call a set $\mathcal M$ rapidly growing with respect to $n$, if 
\begin{equation}\label{eq:rapidGrow}
  \begin{cases}
      \tau^\star(\omega, \mathcal M) \leq t \quad \text{or} \quad \operatorname{rad}(\varphi(t,\omega, \mathcal M)) \geq r_{m(n,t)},& \text{for all } t>0 \text{ with } m(n,t) < \infty, \\
      \tau^\star(\omega, \mathcal M) \leq t,& \text{for all } t>0 \text{ with } m(n,t) = \infty.
  \end{cases}
    \end{equation}

    Suppose that
    \begin{enumerate}
        \item[(i)] for all $n\geq 2$ and all $x,y \in \mathbb R^d$ with $|x|=r_n$ and $|y|=r_{n-1}$, we have
        \begin{equation}\label{eq:growthBound}
            \mathbb P(\tau_{n+1}(x)\wedge \tau_{n+1}(y) \leq \tau_{n-1}(x) \wedge t_n) \geq p^*.
        \end{equation}
        \item[(ii)]
       We have
        \begin{equation}\label{eq:anchorBound}
            \lim_{n \to \infty}\inf_{x\in B_1}\mathbb P(|\varphi(t, \omega,x)| \leq r_{m(n,t)}, ~\forall\,t\in \mathbb R_{>0}) = 1,
        \end{equation}
        where we set $r_\infty \coloneqq \infty.$
    \end{enumerate}
    Let $\mathcal I_n$ denote the family of all connected compact subsets of $\mathbb R^d$ that intersect $B_1$ and have radius at least $r_n$.

    Then the sequence 
    $$p_n \coloneqq \inf_{\mathcal M \in \mathcal I_{2n}} \mathbb P\left(\mathcal M \text{ grows rapidly with respect to } n\right)$$
    is positive for sufficiently large $n$ and converges to 1 as $n \to \infty$.

\label{cor:BlowUp}
    Let the assumptions of Lemma \ref{lemm:BlowUpCrit} hold. 
    \begin{enumerate}
        \item[(i)] Then $\varphi$ does not admit a weak set attractor.
        \item[(ii)] If furthermore $\sum_{i=2}^\infty t_i < \infty$, then $\varphi$ is not strongly complete, and for every $\varepsilon>0$, there exists an $n\in \mathbb N$, such that
        \begin{equation}\label{eq:quickBlowUp}
            \mathbb P(\tau^\star(\omega, \mathcal M) <\varepsilon)>1-\varepsilon\quad \forall\, \mathcal M \in \mathcal I_n,
        \end{equation}
        where $\mathcal I_n$ is the family of sets defined in Lemma \ref{lemm:BlowUpCrit}.
    \end{enumerate}

\label{prop:elemIneq}
    As in the proof of Lemma \ref{lemm:BlowUpCrit}, let $n \in \mathbb N$, $\alpha \in (0,1)$, and $t_2, t_3 , \dots$ be a decreasing sequence of positive real numbers. Also, let $K_i\coloneqq n+\lceil \alpha i\rceil$. Then, for all $i^*\in \mathbb N$ we have
    $$\sum_{i = 0}^{i^*} t_{K_i+1} < \frac{1}{\alpha} \sum_{k = n}^{K_{i^*}} t_{k+1}.$$

\label{newapproach} Consider the SDE on $E=\Gamma \times S^1$
where $\Gamma \subseteq\mathbb{R}$ is an open interval containing $[-2,1]$, given by
\begin{align}\label{neuesde}
\begin{split}
\mathrm{d} R&= -g(R)\,\mathrm{d} t + \cos (\phi)\,\mathrm{d} W_1(t)+\sin (\phi) \,\mathrm{d} W_2(t),\\
\mathrm{d} \phi &= -h(R)\,\mathrm{d} t + \gamma(R) \big( -\sin (\phi)\,\mathrm{d} W_1(t) + \cos (\phi)\,\mathrm{d} W_2(t)\big),
\end{split}
\end{align}
where  $W_1$ and $W_2$ are independent standard Brownian motions and $\gamma \in C^3(\Gamma, \mathbb R)$ and $g,h \in C^2(\Gamma,\mathbb{R})$. Let $\phi_1^0, \phi_2^0 \in S^1$ and denote by $(R_1(t),\phi_1(t))$ and $(R_2(t),\phi_2(t))$ the forward solutions to \eqref{neuesde} with $(R_1(0),\phi_1(0)) = (0,\phi_1^0)$ and $(R_2(0),\phi_2(0)) = (-1,\phi_2^0)$. For some $\delta \in [0,1)$, define three stopping times $\tau^\uparrow_1, \tau^\downarrow_1$ and $\tau^\uparrow_2$ by 
\begin{align}
    \tau^\uparrow_1 &\coloneqq \inf\{t \geq 0: R_1(t) = 1-\delta\},\nonumber\\
    \tau^\downarrow_1 &\coloneqq \inf\{t \geq 0: R_1(t) = -1\},~\text{and}\nonumber\\
    \tau^\uparrow_2 &\coloneqq \inf\{t \geq 0: R_2(t) = 1-\delta \text{ and } R_2(t')> -2, ~\forall\, t'\in [0,t]\} .\label{eq:tau2up}
\end{align}
 There exist  $\varepsilon^* \in (0,1)$ and $T^* \geq 1$, independent of $\delta, \phi_1^0, \phi_2^0, g, h,$ and $\gamma$, such that
\begin{equation}\label{onehalf}
 p^*:=\inf \mathbb{P}(\tau^\uparrow_1 \wedge \tau^\uparrow_2 \leq \tau^\downarrow_1 \wedge T^*)>\frac 12,
 \end{equation}
where the infimum is taken over all $\delta\in [0,1), \phi_1^0,\phi_2^0 \in S^1$ and all functions $g, h$ and $\gamma$ satisfying 
\begin{align}
    g(R) \in [0, \varepsilon^*] \text{ and } |g'(R)|, |g''(R)| \in [0, 3],&\quad \text{for all }R \in [-2,1],\label{eq:gCond}\\
    h'(R) \in \left[\frac{1}{2}, \frac{3}{2}\right] \text{ and } |h(R)|, |h''(R)| \in [0, 3],&\quad \text{for all }R \in [-2,1],\label{eq:hCond}\\
    |\gamma(R)|,|\gamma'(R)| \in [0,\varepsilon^*] \text{ and } |\gamma''(R)|,|\gamma'''(R)| \in [0,3],&\quad \text{for all }R \in [-2,1].\label{eq:gammaCond}
\end{align}

\label{Key}
Assume the setting of Lemma \ref{newapproach} with $\delta = 0$. There exists $\varepsilon>0$  such that
\begin{equation}\label{key}
\tilde p_2\big(\varepsilon
\big)\coloneqq \tilde p_2(\varepsilon, 13)=\inf \mathbb{P}\Big(\tau^\uparrow_2 \leq 13,\text{ and } |R_1(t)|\leq \tfrac 13 ~ \forall\, t \in [0,13]\Big)>0,
\end{equation}
where the infimum is taken over all $\phi_1^0,\phi_2^0 \in S^1$, and $g,h,\gamma$ satisfying (\ref{eq:gCond}--\ref{eq:gammaCond}) with $\varepsilon^*$ replaced by $\varepsilon$.

\label{prop:anchorCond}
    Let $\varphi$ be the RDS given by \eqref{SDE3}. Assume that, in the setting of Lemma \ref{lemm:BlowUpCrit}, the sequences $(r_n)$, $(t_n)$, and the constant $\alpha$ are chosen in such a way that the function $m$ defined in \eqref{eq:Growthrate} satisfies
    $$r_{m(n,t)} \geq c_n \,e^{ct}, \quad \forall\, n \in \mathbb N, t>0$$
    for some $c>0$ and some sequence of real numbers $c_n$ with $c_n\to \infty$. 

    Then \eqref{eq:anchorBound} holds, that is,
    \begin{equation}\label{eq:anchorBound2}
            \lim_{n \to \infty}\inf_{x\in B_1}\mathbb P(|\varphi(t, \omega,x)| \leq r_{m(n,t)}, ~\forall\,t\in \mathbb R_{>0}) = 1.
        \end{equation}

For $\varepsilon^*>0$ as in Lemma \ref{newapproach}, let $K_2 \coloneqq (\varepsilon^*/2)^{-3}.$ Assume that $\rho$ satisfies the assumptions of Theorem \ref{theo:BlowUp}, that is, there exists an $r^*>0$ for which
    \begin{equation}\label{eq:noSetAttr}
        \limsup_{r \to \infty} \frac{|\rho''(r)|}{|\rho'(r)|} <\infty, \quad\quad |\rho'(r)| \geq K_2\, r^3, \quad \forall\, r\geq r^*
    \end{equation}
    and $|\rho'(r)|$ increases monotonically on $[r^*,\infty)$. In particular, this implies that $\rho'(r)$ has a constant sign on $[r^*,\infty)$.
    Without loss of generality, we assume that $\rho'(r)>0$ on $[r^*,\infty)$. If not, we consider the \eqref{SDE3} with $\rho$ replaced by $-\rho$ which corresponds to replacing $X_1$ by $-X_1$.

    For some large $r_1\geq r^*$, whose exact value will be determined later, we recursively define $r_{n+1}$ in such a way that
    \begin{equation}\label{eq:rRecursion}
        r_{n+1}-r_n = \rho'(r_{n+1})^{-1/3}
    \end{equation}
    holds. This is always possible and the choice is unique since $\rho'(r)^{-1/3}$ is monotonically decreasing and continuous. Note that this is the same definition we used in the proof of Theorem \ref{theo:attractors2} (a). First, we argue that $r_n \to \infty$. If not, taking the limit $n \to \infty$ in Equation \eqref{eq:rRecursion} gives $\rho'(r_{\lim})^{-1/3} = 0$ for the finite limit $r_{\lim} \coloneqq \lim_{n \to \infty} r_n$, which leads to a contradiction. Next, for $n\geq 2$, we set $q_n \coloneqq  \rho'(r_{n})^{-1/3} = r_n - r_{n-1}$ and $t_n = T^* \,q_n^2$, where $T^*$ is as in Lemma \ref{newapproach}. Note that $t_n$ is decreasing as required. We proceed by checking the two main assumptions \eqref{eq:growthBound} and \eqref{eq:anchorBound} of Lemma \ref{lemm:BlowUpCrit}.

    \textbf{Step 1 -- Coordinate Transformation:} For the former, we will show that the condition \eqref{eq:growthBound} holds for the $p^*>\frac{1}{2}$ given in Lemma \ref{newapproach}, that is, for all $n \geq 2$ and all $x, y \in \mathbb R^2$ with $|x|= r_n$ and $|y| = r_{n-1}$, we have
    \begin{equation}\label{ineq:growthGoal}
        \mathbb P(\tau_{n+1}(x)\wedge \tau_{n+1}(y) \leq \tau_{n-1}(x) \wedge t_n) \geq p^*,
    \end{equation}
    where $\tau_n$ and $\tau_{n-1}$ are the stopping times defined in Lemma \ref{lemm:BlowUpCrit}.
     Recall from \eqref{eq:SDE_polar} the polar coordinate representation of \eqref{SDE3}, which evolves according to
     \begin{equation}\label{sde:polar2}
    \begin{aligned}
\mathrm{d} R(t)&=-\left(R(t)-\frac{1}{2R(t)}\right)\,\mathrm{d} t +\cos(\phi(t))\,\mathrm{d} W_1(t) + \sin(\phi(t))\,\mathrm{d} W_2(t),\\
\mathrm{d} \phi(t)&=-\rho(R(t))\,\mathrm{d} t +\frac 1{R(t)}\big(-\sin(\phi(t))\,\mathrm{d} W_1(t) + \cos(\phi(t))\,\mathrm{d} W_2(t)\big).
\end{aligned}
\end{equation}
Fix some $n\geq 2$. In order to show \eqref{ineq:growthGoal}, we specifically care about the dynamics of \eqref{sde:polar2} for values of $R$ between $r_{n-1}$ and $r_{n+1}$. To study these, we introduce new coordinates that zoom in on this region. At the same time, we also slow down the time by a factor of $q_n^2$ and introduce a moving reference frame for $\phi$. The new coordinates are given by 
$$\tilde R(t) = \frac{1}{q_n} (R(q_n^2\, t)-r_n) \quad \quad \tilde \phi(t) = \phi(q_n^2 t) + q_n^2\rho(r_n)\, t.$$
In these coordinates, \eqref{sde:polar2} is given by
     \begin{equation}\label{sde:polar3}
    \begin{aligned}
\mathrm{d} \tilde R(t)&=-g_n(\tilde R(t))\,\mathrm{d} t +\cos(\tilde \phi(t))\,\mathrm{d} \widetilde W_1(t) + \sin(\tilde \phi(t))\,\mathrm{d} \widetilde W_2(t),\\
\mathrm{d} \tilde \phi(t)&=-h_n(\tilde R(t))\,\mathrm{d} t +\gamma_n(\tilde R(t))\big(-\sin(\tilde \phi(t))\,\mathrm{d} \widetilde W_1(t) + \cos(\tilde \phi(t))\,\mathrm{d} \widetilde W_2(t)\big),
\end{aligned}
\end{equation}
where the functions $g_n, h_n,$ and $\gamma_n$ are given by
\begin{align*}
    g_n(\tilde R) &\coloneqq q_n\left(r_n+q_n \tilde R-\frac{1}{2(r_n+q_n\tilde R)}\right),\\
    h_n(\tilde R) &\coloneqq q_n^2 \left(\rho(r_n+q_n\tilde R) - \rho(r_n)\right),\text{ and}\\
    \gamma_n(\tilde R) &\coloneqq \frac{q_n}{r_n+q_n\tilde R},
\end{align*}
and $\widetilde W_1, \widetilde W_2$ are independent Brownian motions that depend on $n$ but not on the trajectory $(\tilde R(t), \tilde \phi(t))$.
Note that \eqref{sde:polar3} is of the form \eqref{neuesde} studied in Lemma \ref{newapproach}. Furthermore, $R = r_{n-1}$ corresponds to $\tilde R = -1$, $R=r_n$ corresponds to $\tilde R = 0$, and $R = r_{n+1}$ corresponds to $\tilde R = 1-\delta_n$, for $\delta_n \coloneqq 1-q_{n+1}/q_n \in [0,1)$. Moreover, the time $t_n = q_n^2 \, T^*$ in \eqref{sde:polar2} corresponds to the time $T^*$ in \eqref{sde:polar3}. Thus, in order to establish \eqref{ineq:growthGoal}, it is sufficient to show that $g_n, h_n$ and $\gamma_n$ satisfy the conditions of Lemma \ref{newapproach}, given that $r_1$ was chosen sufficiently large.

\textbf{Step 2 -- Verifying (\ref{eq:gCond}--\ref{eq:gammaCond}):} First note that, for each $n\geq 2$, we have
\begin{equation}\label{ineq:rnqn}
    r_n \, q_n = r_n \, \rho'(r_n)^{-1/3} \leq \varepsilon^*/2<1/2.
\end{equation}
Fix $n\geq 2$ and $\tilde R \in [-2,1]$. Write $S \coloneqq S(n, \tilde R) \coloneqq r_n+q_n \tilde R \in [r_n-2q_n, r_n+ q_n]$. We have
$$g_n(\tilde R) = q_n\left(S-\frac{1}{2S}\right),\quad h_n(\tilde R) = q_n^2 (\rho(S)-\rho(r_n)), \text{ and}\quad \gamma_n (\tilde R) = \frac{q_n}{S}.$$
 Prescribe $r_1\geq 2$. Consequently $r_n\geq 2$ and $q_n \leq \varepsilon^*/4 < 1/4$. In particular, we have $S\geq r_n-2q_n > 3/2$. Thus $g_n(\tilde R) > 0$. Furthermore, 
$$g_n(\tilde R) \leq q_n \,S \leq q_n r_n +q_n^2 \leq \frac{\varepsilon^*}{2} + \frac{\varepsilon^{*2}}{4} \leq \varepsilon^*.$$
We verified $g_n(\tilde R) \in [0,\varepsilon^*]$. For the first two derivatives of $g_n$, we have
\begin{align*}
    |g'_n(\tilde R)| &= q_n^2\left(1+\frac{1}{2S^2}\right) < \frac{1}{16}\left(1+\frac{1}{2(3/2)^2}\right)< 3,\quad\text{and}\\
    |g''_n(\tilde R)| &= \frac{q_n^3}{S^3} < \frac{(1/4)^3}{(3/2)^3}<3.
\end{align*}
We proceed to check the conditions for $h_n$ and its derivatives. By \eqref{eq:noSetAttr}, there exists an $L>0$ and an $R^*\geq r^*$ such that $|\rho''(r)|/\rho'(r) \leq L$ for all $r\geq R^*$. In addition to the previous assumptions, prescribe $r_1 \geq (R^*+1/2) \vee 4L$ such that, in particular, $S\geq R^*$ and $q_n\, L \leq q_n\, r_n/4 < 1/8$. We have
$$h_n'(\tilde R) = q_n^3\rho'(S) = \frac{\rho'(S)}{\rho'(r_n)},$$
and thus
\begin{align*}
    |\log(h'_n(\tilde R))| &= |\log(\rho'(S))-\log(\rho'(r_n))| = \left|\int_{r_n}^S\frac{\rho''(r)}{\rho'(r)}\, \mathrm{d} r\right|\\
    &\leq |S-r_n|\, L \leq 2q_n\,L  <\frac{1}{4}.
\end{align*}
Since $1/2<e^{-1/4}$ and $e^{1/4} < 3/2$, can conclude $h_n'(\tilde R) \in [1/2, 3/2]$. By the same argument, we have $|h_n'(R)| \leq 3/2$ for all $R\in [-2,1]$. Together with $h_n(0) = 0$, we can conclude $|h_n(\tilde R)| \leq 3$ by the mean value theorem. For the second derivative we have
$$|h_n''(\tilde R)| = q_n^4\, |\rho''(S)| =  q_n \frac{|\rho''(S)|}{\rho'(r_n)} \leq q_n \, L \, \frac{\rho'(S)}{\rho'(r_n)} <\frac{1}{4}\,h_n'(\tilde R) \leq \frac{3}{8}<3. $$
Finally, we check the conditions for $\gamma_n$ and its derivatives. We have
$$|\gamma_n(\tilde R)| = \frac{q_n}{S}, \quad |\gamma'_n(\tilde R)| = \frac{q_n^2}{S^2}, \quad |\gamma''_n(\tilde R)| = 2\frac{q_n^3}{S^3}, \quad \text{and}\quad |\gamma'''_n(\tilde R)| = 6\frac{q_n^4}{S^4}.$$
The required bounds follow directly from $q_n/S < (\varepsilon^*/4)/(3/2) = \varepsilon^*/6$ and $\varepsilon^*<1$. Thus, Lemma \ref{newapproach} establishes \eqref{eq:growthBound}.

\textbf{Step 3 -- Controlling the One-Point Growth:}
In order to verify \eqref{eq:anchorBound} using Proposition \ref{prop:anchorCond}, we show that $t \mapsto m(n,t)$ is growing exponentially. Using $r_{k+1}\, q_{k+1} \leq \varepsilon^*/2$, see \eqref{ineq:rnqn}, we get
$$\log(r_{k+1})-\log(r_k) = \int_{r_k}^{r_{k+1}} \frac{1}{s}\, \mathrm{d} s \geq \frac{r_{k+1}-r_k}{r_{k+1}} = \frac{q_{k+1}}{r_{k+1}} \geq \frac{2}{\varepsilon^*} \, q_{k+1}^2 = \frac{2}{\varepsilon^*T^*} \, t_{k+1},$$
for all $k \in \mathbb N$. Summing this from $k=n$ to $k=m(n,t)-1$ for some $t>0,$ we obtain
\begin{align*}
    \log(r_{m(n,t)}) -\log(r_n)\geq \frac{2}{\varepsilon^*T^*} \sum_{k=n}^{m(n,t)-1}t_{k+1}.
\end{align*}
By the definition of $m(n,t)$, we have $\sum_{k=n}^{m(n,t)}t_{k+1}\geq \alpha t$ for all $t$ such that $m(n,t)<\infty.$
Thus,
\begin{align}
    \log(r_{m(n,t)}) &\geq \log(r_n) + \frac{2}{\varepsilon^*T^*} \sum_{k=n}^{m(n,t)-1}t_{k+1}\nonumber\\
    &\geq \log(r_n) + \frac{2}{\varepsilon^*T^*} (\alpha t- t_{m(n,t)})\nonumber\\
    &\geq \log(r_n) + \frac{2}{\varepsilon^*T^*} (\alpha t- t_2)\label{eq:expGrowth}
\end{align}
Thus the assumption \eqref{eq:anchorBound} follows from Proposition \ref{prop:anchorCond}.

\textbf{Step 4 -- Completing the Proof:} By Corollary \ref{cor:BlowUp}, $\varphi$ does not admit a set attractor, showing Theorem \ref{theo:BlowUp} (a.i). Also, by \eqref{eq:expGrowth}, every rapidly growing set has an exponentially growing radius. Thus Lemma \ref{lemm:BlowUpCrit} establishes Theorem \ref{theo:BlowUp} (a.iii). For Theorem \ref{theo:BlowUp} (a.ii), we need to show that every compact connected set $\mathcal M$ with at least two points has a positive probability to have an exponentially growing radius. This is not covered by Lemma \ref{lemm:BlowUpCrit}, which only establishes this property for sets $\mathcal M' \in \mathcal I_{2n}$ for some sufficiently large $n$. Using a control theoretic argument, we show in Lemma \ref{lemm:separation} in the appendix that for any two distinct points $x_1 \neq x_2 \in \mathbb R^2$ and any $n\in \mathbb N$, there is a time $T >0$ such that $|\varphi(T,\omega, x_1)|\leq1$ and $|\varphi(T,\omega, x_2)|\geq r_{2n}$ with positive probability. Thus for any compact connected set $\mathcal M$ with at least two points, there is a time $T>0$ such that there is a positive probability such that either $\tau^\star(\omega,\mathcal M) \leq T$ or $\varphi(T,\omega, \mathcal M) \in \mathcal I_{2n}$. In the former case we are done, and in the latter case we can apply Lemma \ref{lemm:BlowUpCrit} and the strong Markov property to conclude Theorem \ref{theo:BlowUp} (a.ii).

In addition to the assumptions of Theorem \ref{theo:BlowUp} (a), assume \eqref{eq:NoCompl}, that is,
    \begin{equation*}
\int_{r^*}^\infty \rho'(r)^{-1/3}\,\mathrm{d} r<\infty,
\end{equation*}
where we assume $ \rho'(r)>0$ for $r\geq r^*$, as before, without loss of generality.  Using $t_i = T^* q_i^2$ and $q_i = r_i -r_{i-1} = \rho'(r_i)^{-1/3}$, as well as the fact that $\rho'(r)^{-1/3}$ for all $r>r_1\geq r^*$ is decreasing, we can compute
    \begin{align*}
        \sum_{i = 2}^\infty t_i = T^* \,\sum_{i = 2}^\infty q_i^2 = T^* \,\sum_{i = 2}^\infty (r_i-r_{i-1}) \rho'(r_i)^{-1/3} \leq T^* \,\int_{r_1}^\infty \rho'(r)^{-1/3}\, \mathrm{d} r < \infty.
    \end{align*}
    By Corollary \ref{cor:BlowUp} (ii), $\varphi$ is not strongly complete, and for every $\varepsilon>0$, there exists an $n \in \mathbb N$, such that
    $$
            \mathbb P(\tau^\star(\omega, \mathcal M) <\varepsilon)>1-\varepsilon\quad \forall\, \mathcal M \in \mathcal I_n,
$$
establishing (b.i) and (b.iii). The remaining statement (b.ii) can be deduced using Lemma \ref{lemm:separation}, analogously to (a.ii).

\label{lemm:separation}
Suppose that $\rho: [0,\infty) \to \mathbb R$ satisfies
\begin{equation}\label{eq:separationCondition}
    \liminf_{r \to \infty} |\rho'(r) r| = \infty.
\end{equation}
Then, for any $x_1, x_2 \in \mathbb R^2$ with $x_1\neq x_2$ and every $M >0$ there exists a time $T\geq 0$ such that
$$\mathbb P\left(|\varphi(T,\omega, x_1)|\leq 1\text{ and } \left|\varphi(T,\omega, x_2)\right|\geq M \right)>0.$$

The condition \eqref{eq:separationCondition} implies that the sign of $\rho'(r)$ is constant for sufficiently large $r$. Without loss of generality, we assume that it is eventually positive implying that $\liminf_{r \to \infty} \rho'(r) r = \infty.$ The following proof is most easily understood by referring to Figure \ref{fig:separation}.

\textbf{Step 1:} Let $\omega_0 \in \Omega$ be the constant path, such that $(\varphi(t, \omega_0, \cdot))_{t\geq 0}$ is the deterministic flow induced by the ODE 
\begin{equation}\label{eq:sepODE}
    \dot X(t)=-\,X(t)+\rho(|X(t)|) \begin{pmatrix}0&1\\-1&0 \end{pmatrix}X(t).
\end{equation}
We first show that for any $\tilde M>0$, $\delta>0$ and any angle $\phi \in [0,2\pi)$, there exists a radius $r^*>0$ and a time $\tilde T\geq 0$ such that
\begin{equation}\label{eq:sepLemmStep1Goal}
    |\varphi(\tilde T, \omega_0, y_1) - \varphi(\tilde T, \omega_0, y_2)| \geq \tilde M, \quad \text{where } y_1 \coloneqq r^* \begin{pmatrix}\cos \phi\\ \sin \phi\end{pmatrix},~y_2 \coloneqq (r^*+\delta) \begin{pmatrix}\cos \phi\\ \sin \phi\end{pmatrix}.
\end{equation}
Suppose that $\tilde M>\delta$, since otherwise $\tilde T = 0$ and any $r^*>0$ suffices. Choose $r^* \geq \tilde M>\delta$ such that
\begin{equation}\label{eq:sepLemmaShearCond}
    \rho'(r) r \geq \frac{4\pi \tilde M}{\log (2) \delta}, \quad \forall\, r\geq \frac {r^*} 2.
\end{equation}
Let $(Y_1(t))_{t\geq 0}$, $(Y_2(t))_{t\geq 0}$ be the solutions to the ODE \eqref{eq:sepODE} with initial values $Y_1(0) = y_1$ and $Y_2(0) = y_2$.
Let $R_1(t), R_2(t)$ and $\phi_1(t), \phi_2(t)$ be the polar coordinate representations of $Y_1(t), Y_2(t)$ such that
$$Y_{1/2}(t) = R_{1/2}(t) \begin{pmatrix}\cos \phi_{1/2}(t)\\ \sin \phi_{1/2}(t)\end{pmatrix}.$$
We have $R_1(0) = r^*,$ $R_2(0) = r^*+\delta$, $\phi_1(0) = \phi_2(0) = \phi$ and by \eqref{eq:SDE_polar} with $c = 1$ and $\sigma = 0$
$$\dot R_{1/2}(t) = - R_{1/2}(t), \quad \dot \phi_{1/2}(t) = -\rho(R_{1/2}(t)).$$
We can compute $R_1(t) = r^* e^{-t}$ and $R_2(t) = (r^*+\delta) e^{-t}$. In particular, for all $t \in [0,\log 2]$, we have $r^*/2 \leq R_{1/2}(t) \leq r^* +\delta \leq 2r^*$ and $R_2(t)-R_1(t) \geq  \delta/ 2$. By the mean value theorem and by \eqref{eq:sepLemmaShearCond}, we have
\begin{align*}
    \rho(R_2(t)) - \rho(R_1(t)) &\geq (R_2(t)-R_1(t))\inf_{r \in [R_1(t), R_2(t)]} \rho'(r) \\
    &\geq \frac{\delta}{2} \frac{4\pi \tilde M}{\log (2)\delta R_2} \geq \frac{\pi \tilde M}{ \log(2) r^*},
\end{align*}
for each $t\in [0,\log 2]$. Choosing compatible lifts on $\mathbb R$ of the angles $\phi_{1/2}(t) \in [0,2\pi)$, we get
$$\phi_1(\log 2) -\phi_2(\log 2) = \int_0^{\log 2} (\rho(R_2(t)) - \rho(R_1(t)))\,\mathrm{d} t \geq \frac{\pi \tilde M}{ r^*}.$$
Let $\tilde T \in (0,\log 2]$ be the first time that $\phi_1(\tilde T) -\phi_2(\tilde T) = \pi \tilde M/ r^*\leq \pi$. We use the cosine law and the inequality $\sin(\pi\alpha/2) \geq \alpha, ~\forall\, \alpha \in [0,1]$, to compute
\begin{align*}
    |Y_1(\tilde T)-Y_2(\tilde T)| &= \sqrt{R_1(\tilde T)^2 + R_2(\tilde T)^2 - 2 R_1(\tilde T)R_2(\tilde T) \cos(\phi_1(\tilde T) -\phi_2(\tilde T))}\\
    &\geq \frac{r^*}{2} \sqrt{2-2 \cos\Big(\frac{\pi \tilde M}{ r^*}\Big)} = r^* \sin\Big(\frac{\pi \tilde M}{ 2 r^*}\Big) \geq \tilde M.
\end{align*}
Furthermore, it follows from exact solutions to $R_1$ and $R_2$ that
$$\max(|Y_1|, |Y_2|) \leq {r^*+\delta} \leq 2r^*.$$

\textbf{Step 2:} We apply the support theorem to each step described in Figure \ref{fig:separation}. Let $x_1\neq x_2 \in \mathbb R^2$ be two distinct points and $M>0$. Let $\delta \coloneqq |x_1-x_2|$ be their distance and $\phi \in [0, 2\pi]$ be the phase of their difference such that 
$$x_2-x_1 = \delta \begin{pmatrix}\cos \phi\\\sin \phi\end{pmatrix}.$$
Also, let $\tilde M = M+3$ and $\tilde T\geq 0$, $r^*>0$, $y_1, y_2\in \mathbb R^2$ as in Step 1. Note that $y_1-x_1 = y_2 -x_2$. By continuity of the flow, there exists an $\varepsilon>0$, such that 
\begin{align*}
     |\varphi(\tilde T, \omega_0, \tilde y_1) - \varphi(\tilde T, \omega_0, \tilde y_2)| &\geq \tilde M-1= M+2, \quad \text{and}\\
     |\varphi(\tilde T, \omega_0, \tilde y_1)| \vee |\varphi(\tilde T, \omega_0, \tilde y_2)|&\leq 2r^*+1,
\end{align*}
for all $\tilde y_1 \in B_{y_1}(\varepsilon), \, \tilde y_2 \in B_{y_2}(\varepsilon)$. 
By the Stroock-Varadhan support theorem \cite{StrookVaradhan72}, we furthermore have
\begin{equation}\label{eq:sepLemmaProb1}
    \mathbb P(|\varphi(\tilde T, \omega, \tilde y_1) - \varphi(\tilde T, \omega, \tilde y_2)| \geq M+1 \text{ and }  |\varphi(\tilde T, \omega, \tilde y_1)|\vee |\varphi(\tilde T, \omega, \tilde y_2)|\leq 2r^*+2)>0,
\end{equation}
By applying the support theorem to the two-point motion, there exists a small time  ${0<T_\varepsilon\ll 1}$, such that
\begin{align}
    &\quad~\mathbb P(\varphi(T_\varepsilon, \omega, x_1) \in B_{y_1}(\varepsilon) \text{ and } \varphi(T_\varepsilon, \omega, x_2)\in B_{y_2}(\varepsilon))\nonumber \\
    &= \mathbb P(\varphi(T_\varepsilon, \omega, x_1)-x_1 \in B_{y_1-x_1}(\varepsilon) \text{ and } \varphi(T_\varepsilon, \omega, x_2)-x_2\in B_{y_2-x_2}(\varepsilon))>0,\label{eq:sepLemmaProb2}
\end{align}
where we use the fact that $y_1-x_1 = y_2 -x_2$, as well as,
\begin{align}
&\quad~\mathbb P (|\varphi(T_\varepsilon, \omega, z_1)|\leq 1 \text{ and } |\varphi(T_\varepsilon, \omega, z_2)| \geq M)\nonumber\\
&\geq \mathbb P (\varphi(T_\varepsilon, \omega, z_1) - z_1 \in B_{-z_1}(1) \text{ and } \varphi(T_\varepsilon, \omega, z_2) - z_2 \in B_{-z_1}(1))>0\label{eq:sepLemmaProb3},
\end{align}
for all $z_1, z_2 \in \mathbb R^2$ with $|z_1-z_2|\geq M+1$ and $|z_1|, |z_2| \leq 2r^* +2.$

\textbf{Step 3:} We conclude the proof of the lemma. Set
\begin{align*}
\tilde y_{1/2} \coloneqq \varphi(T_\varepsilon, \omega, x_{1/2}),\quad\text{and}\quad z_{1/2} \coloneqq \varphi(T_\varepsilon+\tilde T, \omega, x_{1/2}) = \varphi(\tilde T, \theta_{T_\varepsilon} \omega, \tilde y_{1,2}).
\end{align*}
By \eqref{eq:sepLemmaProb2}, we have 
$$\mathbb P(\tilde y_1 \in B_{y_1}(\varepsilon) \text{ and }\tilde y_2 \in B_{y_2}(\varepsilon)) >0.$$
By \eqref{eq:sepLemmaProb1}, we have
$$\mathbb P(|z_1-z_2|\geq M+1\text{ and } |z_1|\vee |z_2| \leq 2r^*+2\mid \tilde y_1 \in B_{y_1}(\varepsilon) \text{ and }\tilde y_2 \in B_{y_2}(\varepsilon)) >0.$$
Finally, by \eqref{eq:sepLemmaProb3}, we have
\begin{multline*}
    \mathbb P\big(|\varphi(T_\varepsilon,\theta_{T_\varepsilon+\tilde T}\omega, z_1)|\leq 1 \text{ and } |\varphi(T_\varepsilon,\theta_{T_\varepsilon+\tilde T}\omega, z_2)|\geq M \\
    \big|\, |z_1-z_2|\geq M+1 \text{ and } |z_1|\vee|z_2|\leq 2r^*+2\big)>0.
\end{multline*}
Setting $T\coloneqq 2T_\varepsilon + \tilde T$, we conclude 
\begin{align*}
    \mathbb P\left(|\varphi(T,\omega, x_1)|\leq 1\text{ and } \left|\varphi(T,\omega, x_2)\right|\geq M \right)>0.
\end{align*}
